dtsPropsFor.AppRail:
/** 当前高亮的屏 */
active: 'entry' | 'review' | 'history' | 'prompt' | 'settings';
/** 无活跃 review 时「当前审核」不可达 */
reviewAvailable: boolean;
/** 新版已下好、只差重启 —— 设置钮挂未读点 */
updateReady?: boolean;
onNavigate: (s: 'entry' | 'review' | 'history' | 'prompt' | 'settings') => void;

dtsPropsFor.CapacityNotice:
/** 并发容量快照:坐满且每个都在跑才算满载 */
capacity: { max: number; live: number; busy: Array<{ reviewId: string; title: string; sourceRef: string; source: 'github-pr' | 'local-branch' | 'gitbutler-vbranch'; round: number; /** true = 在机审扫描;false = 在回答追问 */ scanning: boolean }> };
/** 这次被挡下的是什么;缺省「暂时开不了新的」 */
blocked?: string;
/** 直达在跑的那条 review;不给 = 渲染成不可点的纯文本 */
onOpen?: (reviewId: string) => void;
onRefresh: () => void;
/** 常驻拦截(入口屏发起门控)不该有出口,故可选 */
onDismiss?: () => void;
/** 悬浮呈现:review 屏是三栏满屏,没有能嵌进去的流式位置 */
float?: boolean;

dtsPropsFor.CompletionToast:
/** 长任务完成提示的载荷 */
notice: { reviewId: string; kind: 'scan-done' | 'reply'; title: string; body: string; /** 追问回复所属 discussion;scan-done 无 */ discussionId?: string };
onOpen: (reviewId: string) => void;
onDismiss: () => void;

dtsPropsFor.LensScanArt:
/** 点亮的行数 = 已完成的阶段数,让画面带一点真实进度 */
lit?: number;
/** 失败态:扫描停住、镜片居中转红环 */
failed?: boolean;
className?: string;

dtsPropsFor.ReviewTabs:
/** 打开着的 review;reviewId 即身份 */
tabs: ReadonlyArray<{ reviewId: string; view: 'review' | 'submit' }>;
activeId: string | null;
meta: Record<string, { title: string; sourceRef: string; source: 'github-pr' | 'local-branch' | 'gitbutler-vbranch'; /** github 源可以没有 */ repoPath: string | null; status: 'scanning' | 'reviewing' | 'completed' | 'submitted' | 'failed' | null; /** 后台期间新报出的 finding 数;激活即清零 */ unread: number }>;
/** tab 条右侧的一句轻提示;sticky = 不自动消失 */
notice: { text: string; action?: { label: string; onRun: () => void }; sticky?: boolean } | null;
onActivate: (reviewId: string) => void;
onClose: (reviewId: string) => void;
/** ＋:回入口发起新审核 */
onNew: () => void;

dtsPropsFor.ScreenPlaceholder:
title: string;
/** 一句话说明该屏怎么进来 / 为何现在是空的 */
hint: string;
parts: string[];

dtsPropsFor.StartSteps:
/** 阶段表;每档带一句滞留过久时的等待预期 */
steps: Array<{ stage: 'resolve' | 'diff' | 'record' | 'agent'; label: string; slow: string }>;
/** 当前阶段,来自后端真实回调 */
stage: 'resolve' | 'diff' | 'record' | 'agent';
/** 未进入慢档时的常态提示 */
hint: string;
